import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique file inside {@code dir} using {@code name}. The method
     * protects against directory‑traversal attacks by normalizing the supplied
     * name and ensuring that the resolved path stays within {@code dir}.
     *
     * @param dir  the base directory where the file should be created
     * @param name the requested file name (may contain query parameters)
     * @return a {@link File} object pointing to a non‑existing file inside {@code dir}
     * @throws IllegalArgumentException if the resolved path is outside {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Directory cannot be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("Name cannot be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Normalize the supplied name to eliminate '..', './', etc.
        Path normalizedName = Paths.get(name).normalize();

        // Resolve against the target directory and verify containment
        Path targetPath = dir.toPath().resolve(normalizedName).normalize();
        if (!targetPath.startsWith(dir.toPath().normalize())) {
            throw new IllegalArgumentException(
                "Attempt to create a file outside the target directory: " + name);
        }

        File file = targetPath.toFile();

        // Handle duplicate names by appending "-n" before the extension
        int dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Ensure parent directories exist
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }

        return file;
    }

    // other methods
}
