import java.io.File;
import java.io.FileNotFoundException;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.Date;
import org.codehaus.plexus.archiver.util.ArchiveEntryUtils;
import org.codehaus.plexus.components.io.attributes.SymlinkUtils;
import org.codehaus.plexus.logging.AbstractLogEnabled;
import org.codehaus.plexus.util.FileUtils;
import org.codehaus.plexus.util.IOUtil;
import org.codehaus.plexus.util.StringUtils;

public abstract class AbstractUnArchiver extends AbstractLogEnabled implements UnArchiver, FinalizerEnabled {

    private boolean overwrite = true;
    private boolean ignorePermissions = false;

    // other methods

    /**
     * Extracts a single entry from an archive into the specified directory.
     *
     * <p>This method now performs a strict canonical path check to guard against
     * Zip‑Slip attacks. The resolved destination file must reside within the
     * target {@code dir}. Any attempt to write outside this directory will
     * result in an {@link ArchiverException}.</p>
     *
     * @param srcF              the source file (unused in this implementation)
     * @param dir               the base directory where files are extracted
     * @param compressedInputStream the input stream of the compressed entry
     * @param entryName         the name of the entry inside the archive
     * @param entryDate         the modification time of the entry
     * @param isDirectory       whether the entry represents a directory
     * @param mode              the Unix permission mode (may be {@code null})
     * @param symlinkDestination the target of a symbolic link (may be {@code null})
     * @throws IOException      if an I/O error occurs
     * @throws ArchiverException if the entry is outside the target directory
     */
    protected void extractFile(final File srcF,
                               final File dir,
                               final InputStream compressedInputStream,
                               final String entryName,
                               final Date entryDate,
                               final boolean isDirectory,
                               final Integer mode,
                               String symlinkDestination) throws IOException, ArchiverException {

        // Resolve the destination file
        final File f = FileUtils.resolveFile(dir, entryName);

        // Canonicalize both the target directory and the destination file
        final Path canonicalDirPath = dir.getCanonicalFile().toPath();
        final Path canonicalDestPath = f.getCanonicalFile().toPath();

        // Ensure the destination is a subpath of the target directory
        if (!canonicalDestPath.startsWith(canonicalDirPath)) {
            throw new ArchiverException("Entry is outside of the target directory (" + entryName + ")");
        }

        try {
            // Skip extraction if overwrite is disabled and the file is up-to-date
            if (!isOverwrite() && f.exists() && (f.lastModified() >= entryDate.getTime())) {
                return;
            }

            // Create parent directories if necessary
            final File dirF = f.getParentFile();
            if (dirF != null) {
                dirF.mkdirs();
            }

            // Handle symbolic links
            if (!StringUtils.isEmpty(symlinkDestination)) {
                SymlinkUtils.createSymbolicLink(f, new File(symlinkDestination));
            } else if (isDirectory) {
                f.mkdirs();
            } else {
                // Write file contents using a try‑with‑resources block
                try (OutputStream out = new FileOutputStream(f)) {
                    IOUtil.copy(compressedInputStream, out);
                }
            }

            // Preserve the original modification time
            f.setLastModified(entryDate.getTime());

            // Apply Unix permissions if requested
            if (!isIgnorePermissions() && mode != null && !isDirectory) {
                ArchiveEntryUtils.chmod(f, mode);
            }
        } catch (final FileNotFoundException ex) {
            getLogger().warn("Unable to expand to file " + f.getPath());
        }
    }

    // other methods

    @Override
    public boolean isIgnorePermissions() {
        return ignorePermissions;
    }

    @Override
    public boolean isOverwrite() {
        return overwrite;
    }
