import java.io.IOException;
import java.io.InputStream;

class RgbeInfo implements Closeable {

    private final InputStream in;

    // other methods

    /**
     * Decompresses data from {@code in} into {@code out} using a simple
     * run‑length encoding scheme. The method performs extensive validation
     * to guard against malformed input that could otherwise cause an
     * infinite loop or buffer overflow.
     *
     * @param in  the source stream containing compressed data
     * @param out the destination array that will receive the decompressed bytes
     * @throws IOException if the stream ends unexpectedly or the data is
     *                     inconsistent with the expected format
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        int position = 0;
        final int total = out.length;

        while (position < total) {
            int n = in.read();
            if (n == -1) {
                throw new EOFException("Unexpected end of stream while reading control byte");
            }

            // A value of 0 is not valid in this RLE format and would cause an infinite loop.
            if (n == 0) {
                throw new IOException("Invalid RLE packet: zero length encountered");
            }

            if (n > 128) { // repeat packet
                int value = in.read();
                if (value == -1) {
                    throw new EOFException("Unexpected end of stream while reading repeat value");
                }

                int repeatCount = n & 0x7F; // lower 7 bits give the repeat count (1–127)

                if (position + repeatCount > total) {
                    throw new IOException("Compressed data exceeds output buffer size");
                }

                byte v = (byte) value;
                for (int i = 0; i < repeatCount; i++) {
                    out[position++] = v;
                }
            } else { // literal packet
                int copyCount = n; // 1–127

                if (position + copyCount > total) {
                    throw new IOException("Compressed data exceeds output buffer size");
                }

                for (int i = 0; i < copyCount; i++) {
                    int b = in.read();
                    if (b == -1) {
                        throw new EOFException("Unexpected end of stream while reading literal data");
                    }
                    out[position++] = (byte) b;
                }
            }
        }
    }

    // other methods

}
