import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.apache.commons.compress.archivers.ArchiveEntry;

/**
 * Utility class that safely expands archive entries into a target directory.
 */
public class Expander {

    // other methods

    /**
     * Expands all readable entries from the supplied {@link ArchiveEntrySupplier} into the
     * {@code targetDirectory}.  The method performs rigorous path validation to protect
     * against path‑traversal attacks.  It rejects entries whose names contain
     * absolute paths, back‑slashes, or any component that could resolve outside the
     * target directory after canonicalisation.
     *
     * @param supplier        provides the next readable entry
     * @param writer          writes the entry data to an {@link OutputStream}
     * @param targetDirectory the directory into which the archive will be expanded
     * @throws IOException if an I/O error occurs or a path traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical path of the target directory once.
        final Path canonicalTargetDir = targetDirectory.getCanonicalFile().toPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            // Reject obviously malicious entry names early.
            String entryName = nextEntry.getName();
            if (entryName == null || entryName.isEmpty()
                    || entryName.contains("..")
                    || Paths.get(entryName).isAbsolute()
                    || entryName.contains("\\") // Windows style separator
                    || entryName.startsWith(File.separator)) {
                throw new IOException("Invalid entry name: " + entryName);
            }

            // Resolve the entry path relative to the target directory and normalise it.
            Path entryPath = canonicalTargetDir.resolve(entryName).normalize();

            // Ensure the resolved path stays within the target directory.
            if (!entryPath.startsWith(canonicalTargetDir)) {
                throw new IOException("Entry '" + entryName
                        + "' would expand outside of the target directory");
            }

            File f = entryPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("Failed to create directory " + f);
                }
            } else {
                // Ensure parent directories exist.
                File parent = f.getParentFile();
                if (parent != null && !parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("Failed to create directory " + parent);
                }

                // Write the entry data.
                try (OutputStream out = Files.newOutputStream(entryPath)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods
}
