private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Handle entries that use a data descriptor – the data is already cached.
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry(); // cache the entry
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize();

    // Sanity‑check the declared size. A negative size is invalid for a STORED entry.
    if (csize < 0) {
        throw new IOException("Invalid entry size: " + csize);
    }

    // If the entry has no data, signal EOF immediately.
    if (csize == 0) {
        return -1;
    }

    // If we have already read the declared amount, signal EOF.
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Prevent reading past the declared size – this protects against malformed
    // or malicious archives that advertise a larger size than the actual data.
    long remaining = csize - current.bytesRead;
    if (remaining <= 0) {
        return -1;
    }

    // Refill the internal buffer if it is exhausted.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        final int l = in.read(buf.array());
        if (l == -1) {
            // Unexpected end of stream before the declared size was reached.
            throw new IOException("Unexpected end of stream while reading entry: "
                    + current.entry.getName());
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;

        // Detect corruption: if we have read more bytes than the declared size.
        if (current.bytesReadFromStream > csize) {
            throw new IOException("Corrupt entry: read more bytes (" + current.bytesReadFromStream
                    + ") than declared size (" + csize + ")");
        }
    }

    // Determine how many bytes to copy from the buffer.
    int toRead = Math.min(buf.remaining(), length);
    if (remaining < toRead) {
        toRead = (int) remaining;
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}
